int dp[N][N][2], sum[N][2], n, m;
int fac[N], ifac[N], lim[N], pow2[N], ans;

int spow(long long base, int exponent) {
    long long result = 1;
    while (exponent) {
        if (exponent & 1) {
            result = result * base % MOD;
        }
        base = base * base % MOD;
        exponent >>= 1;
    }
    return static_cast<int>(result);
}

int C(int x, int y) {
    return static_cast<int>(
        1LL * fac[x] * ifac[y] % MOD * ifac[x - y] % MOD
    );
}

int ADD(int x, int y) {
    x += y;
    return x >= MOD ? x - MOD : x;
}

void init() {
    fac[0] = ifac[0] = pow2[0] = 1;

    for (int i = 1; i <= 32; ++i) {
        fac[i] = static_cast<int>(1LL * fac[i - 1] * i % MOD);
        pow2[i] = static_cast<int>(2LL * pow2[i - 1] % MOD);
    }

    ifac[32] = spow(fac[32], MOD - 2);
    for (int i = 31; i >= 1; --i) {
        ifac[i] = static_cast<int>(1LL * ifac[i + 1] * (i + 1) % MOD);
    }

    for (int i = 1; i <= 32; ++i) {
        for (int j = 0; j <= i; ++j) {
            sum[i][j & 1] = ADD(sum[i][j & 1], C(i, j));
        }
    }

    while (n) {
        lim[++m] = n & 1;
        n >>= 1;
    }
    std::reverse(lim + 1, lim + m + 1);
}

int main() {
    std::scanf("%d", &n);
    init();

    dp[0][0][1] = 1;

    for (int i = 1; i <= m; ++i) {
        dp[i][0][0] = 1;
