    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= i; ++j) {
            dp[i][j][0] = ADD(
                static_cast<int>(1LL * dp[i - 1][j][0] * pow2[j] % MOD),
                dp[i - 1][j - 1][0]
            );

            if (lim[i]) {
                dp[i][j][0] = ADD(
                    dp[i][j][0],
                    static_cast<int>(1LL * dp[i - 1][j][1] * sum[j][0] % MOD)
                );
                dp[i][j][1] = ADD(
                    dp[i - 1][j - 1][1],
                    static_cast<int>(1LL * dp[i - 1][j][1] * sum[j][1] % MOD)
                );
